import fs from 'node:fs/promises';import {createHmac} from 'node:crypto';
const headers={apikey:process.env.SUPABASE_KEY,Authorization:'Bearer '+process.env.SUPABASE_KEY,'Content-Type':'application/json',Prefer:'return=representation'};
async function db(t,q={},method='GET',body){const r=await fetch(process.env.SUPABASE_URL+'/rest/v1/'+t+'?'+new URLSearchParams(q),{method,headers,body:body?JSON.stringify(body):undefined});if(!r.ok)throw Error('CRM '+r.status);return r.status===204?[]:r.json();}
const secret=process.env.AUTH_SECRET.replace(/\\r|\\n|\r|\n/g,'').trim();if(secret.includes('SENSITIVE'))throw Error('No authentication');
const token=Buffer.from(JSON.stringify({role:'owner',name:'John',exp:Date.now()+300000})).toString('base64url');const cookie='mc_session='+token+'.'+createHmac('sha256',secret).update(token).digest('base64url');
const messages=[
 {key:'amanda-marketing-ack',id:'18204ac7-41b6-50ff-9d8e-ec428947a8f4',source:'c882f45b-9f62-4c66-8ac6-04a2681b5527',channel:'sms',endpoint:'send-reply',payload:{body:"That's a great use for it, Amanda—thank you! Feel free to include the card in your buyer packages. Clients can mention AMANDA15 when they contact us, and we'll include your 15% discount in their quote. Looking forward to working together! — John"}},
 {key:'kingsville-bia-close',id:'799ddedd-d089-4158-a793-8d64dd4c9a14',source:'b4420b69-f58f-4a84-a3ff-28fd08a3da57',channel:'email',endpoint:'send-email',payload:{sender:'john',subject:'RE: Moving support for your team',body:"Hi Jodie,\n\nThanks for clarifying. Understood—there isn't a supplier process to pursue.\n\nIf a member ever needs help with an office move or furniture transfer in Kingsville, you're welcome to pass along my details. I appreciate your time.\n\nJohn Owolabi\nSaturn Star Movers\nbusiness@starmovers.ca | (226) 773-2993\nstarmovers.ca\n3608 Seminole Street, Unit 3, Windsor, ON N8Y 1Y4"}},
];
for(const m of messages){const path='partnership-system/state/'+m.key+'-20260916.json';let previous;try{previous=JSON.parse(await fs.readFile(path))}catch(e){if(e.code!=='ENOENT')throw e;}if(previous){console.log(JSON.stringify({key:m.key,state:'existing_attempt_inspect_receipt'}));continue;}
const [latest]=await db('market_touches',{contact_id:'eq.'+m.id,channel:'eq.'+m.channel,direction:'eq.inbound',order:'created_at.desc',limit:1});if(latest?.id!==m.source)throw Error('New reply needs review '+m.key);
const after=await db('market_touches',{contact_id:'eq.'+m.id,direction:'eq.outbound',created_at:'gt.'+latest.created_at,select:'id,notes,metadata'});if(after.some(t=>!(t.metadata?.provider==='ses'&&t.notes?.startsWith('SES event: '))))throw Error('Conversation already answered '+m.key);
await fs.writeFile(path,JSON.stringify({state:'reserved_no_retry',...m},null,2),{flag:'wx'});
const r=await fetch(`https://go.quote2move.com/api/marketing/contacts/${m.id}/${m.endpoint}`,{method:'POST',headers:{Cookie:cookie,'Content-Type':'application/json'},body:JSON.stringify(m.payload)});const result=await r.json();await fs.writeFile(path,JSON.stringify({state:r.ok?'provider_accepted':'failed',at:new Date().toISOString(),...m,http:r.status,result},null,2));if(!r.ok)throw Error(m.key+' '+JSON.stringify(result));
await db('market_contacts',{id:'eq.'+m.id},'PATCH',{sequence_paused:true,sequence_paused_reason:m.channel==='email'?'No current BIA need or supplier process; no automatic follow-up':'Partner intends to include AMANDA15 in buyer packages; await referrals',next_follow_up:null});
console.log(JSON.stringify({key:m.key,accepted:true,sid:result.sid,messageId:result.messageId}));}
